package mapper;import entity.ThoiGianLamViec;import java.sql.ResultSet;import java.sql.SQLException;import java.time.LocalTime;public class ThoiGianLamViecMapper implements RowMapper<ThoiGianLamViec> {    @Override    public ThoiGianLamViec mapper(ResultSet rs) {        try {            String maLich = rs.getString("maLich");            String ngay = rs.getString("ngay");            LocalTime gioBatDau = Rs.time(rs, "gioBatDau");            LocalTime gioKetThuc = Rs.time(rs, "gioKetThuc");            String maBacSi = rs.getString("maBacSi");            String maChiNhanh = rs.getString("maChiNhanh");            return new ThoiGianLamViec(maLich, ngay, gioBatDau, gioKetThuc, maBacSi, maChiNhanh);        } catch (SQLException e) {            return null;        }    }}